return items.map(item => {

const ocr = item.json.body;

return {

json: {

text: ocr.text,

metadata: {

filename: ocr.filename,

file_type: ocr.type,

ocr: true,

ocr_engine: "easyocr",

confidence: ocr.confidence,

blocks: ocr.blocks,

processed_at:
new Date().toISOString()

}

}

};

});

return items.map(item => {

const doc = item.json;

return {

json: {

text: doc.text,

metadata: {

filename:
doc.metadata.filename,

source:
"google_drive",

type:
doc.metadata.file_type,

ocr:
doc.metadata.ocr,

ocr_engine:
doc.metadata.ocr_engine,

confidence:
doc.metadata.confidence,

blocks:
doc.metadata.blocks,

uploaded_at:
new Date().toISOString(),

document_category:
"image",

status:
"processed"

}

}

};

});

return items.map(item => {

item.json.metadata.status =
"low_confidence";

item.json.metadata.warning =
"OCR confidence below threshold";

return item;

});

return items.map(item => {

item.json.metadata.status =
"empty_document";

item.json.metadata.warning =
"No meaningful text extracted";

return item;

});

return items.map(item => {

return {

json: {

pageContent: item.json.text,

metadata: item.json.metadata

}

};

});

const text = $json.text || "";

return [{
json:{
...$json,

text_length:text.length,

scanned_pdf:text.length<100
}
}];

const item = $input.first();

item.json.metadata.filename =
    item.json.file_name ||
    item.json.metadata.filename;

item.json.metadata.extension =
    item.json.file_extension ||
    item.json.metadata.extension;

delete item.json.file_name;
delete item.json.file_extension;

return [item];

const item = $input.first();

let text = item.json.text || "";

/* normalize whitespace */
text = text.replace(/\s+/g, " ");

/* remove weird repeated chars */
text = text.replace(
  /([A-Za-z])\1{5,}/g,
  "$1"
);

text = text.trim();

/* pageContent */
item.json.pageContent = text;

delete item.json.text;

/* active document */
item.json.active_document =
item.json.metadata?.filename ||
"unknown.pdf";

/* upload time */
item.json.uploaded_at =
new Date().toISOString();

return [item];

return items.map(item=>{

const meta =
item.json.metadata?.metadata
||
item.json.metadata
||
{};

item.json.metadata={

filename:
meta.filename,

extension:
meta.extension,

document_type:
meta.document_type,

pages:
meta.pages,

ocr:
meta.ocr,

confidence:
meta.confidence

};

return item;

});
